const byKey = new Map(MUNICIPALITIES.map((m) => [m.key, m]));

/** The municipality with this key, or undefined when none has it. */
export function municipality(key: string): Municipality | undefined {
  return byKey.get(key);
}

/**
 * The villages that sit inside each town, worked out by testing every point
 * of each village outline against the town outlines. Brockport is the only
 * one that straddles a town line: 76% of it is in Sweden and 24% in
 * Clarkson, so both towns draw it. East Rochester overlaps Perinton the same
 * way but is left out, because it has a section of its own and the site
 * treats it as a town.
 */
const VILLAGES_IN: Record<string, string[]> = {
  sweden: ['brockport'],
  clarkson: ['brockport'],
  ogden: ['spencerport'],
  parma: ['hilton'],
  wheatland: ['scottsville'],
  mendon: ['honeoye-falls'],
  perinton: ['fairport'],
  riga: ['churchville'],
};

/** The villages a town contains, in drawing order. Empty for most towns. */
export function villagesIn(key: string): Municipality[] {
  return (VILLAGES_IN[key] ?? [])
    .map((village) => byKey.get(village))
    .filter((m): m is Municipality => m !== undefined);
}

/** The points of one subpath. Villages sit on top of towns, never as holes. */
type Ring = [number, number][];

/** Splits a municipality's paths into rings, one per subpath. */
function ringsOf(m: Municipality): Ring[] {
  const rings: Ring[] = [];
  for (const d of m.paths) {
    const tokens = d.match(/[A-Za-z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) ?? [];
    let points: Ring = [];
    let command = '';
    let x = 0;
    let y = 0;
    let i = 0;
    const close = () => {
      if (points.length > 2) rings.push([...points, points[0]]);
      points = [];
    };

    while (i < tokens.length) {
      const token = tokens[i];
      if (/[A-Za-z]/.test(token)) {
        command = token;
        i += 1;
        if (command === 'M') close();
        continue;
      }
      const next = () => Number(tokens[i++]);

      switch (command) {
        case 'M':
        case 'L':
          x = next();
          y = next();
          break;
        case 'H':
          x = next();
          break;
        case 'V':
          y = next();
          break;
        case 'C':
          next();
          next();
          next();
          next();
          x = next();
          y = next();
          break;
        default:
          i += 1;
          continue;
      }
      points.push([x, y]);
    }
    close();
  }
  return rings;
}

const ringsByKey = new Map<string, Ring[]>();

/** Crossing count, one ring at a time, so rings read as a union. */
function inRing(ring: Ring, px: number, py: number): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > py !== yj > py && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

/**
 * The town a place falls in, whatever section its page sits under. A park
 * belongs on the map of the town that actually holds it, and the two can
 * disagree: Belmanor Park is filed under Brighton and stands in Henrietta.
 */
export function townAt(
  latitude: number,
  longitude: number
): string | undefined {
  const { x, y } = project(latitude, longitude);
  for (const m of MUNICIPALITIES) {
    if (!m.href?.startsWith('/town-parks/')) continue;
    if (!ringsByKey.has(m.key)) ringsByKey.set(m.key, ringsOf(m));
    if (ringsByKey.get(m.key)!.some((ring) => inRing(ring, x, y))) return m.key;
  }
  return undefined;
}

/**
 * The town or city a place falls in. A county park can stand in the City of
 * Rochester, which `townAt` does not name, so this looks at the city too.
 * Villages are left out: a park in one is drawn on the town around it.
 */
export function placeAt(
  latitude: number,
  longitude: number
): string | undefined {
  const town = townAt(latitude, longitude);
  if (town) return town;
  const { x, y } = project(latitude, longitude);
  const city = byKey.get('rochester')!;
  if (!ringsByKey.has(city.key)) ringsByKey.set(city.key, ringsOf(city));
  return ringsByKey.get(city.key)!.some((ring) => inRing(ring, x, y))
    ? city.key
    : undefined;
}

/**
 * The map key for a town section url, e.g. "/town-parks/gates-parks/" gives
 * "gates". Returns undefined for any other url, and for a town the map does
 * not draw.
 */
export function townKey(url: string): string | undefined {
  const match = /^\/town-parks\/(.+)-parks\/$/.exec(url);
  const key = match?.[1];
  return key !== undefined && byKey.has(key) ? key : undefined;
}

/**
 * True for the county park section. A county park belongs to the whole
 * county, not to one town, so this section is drawn on the county map
 * instead of a town outline. Callers pass the section url, the way they do
 * for `townKey`, so the by-size ordering counts as the section too.
 */
export function isCountySection(url: string): boolean {
  return url === '/monroe-county-parks/';
}

/**
 * Where a latitude and longitude fall in the map's coordinate space.
 *
 * The outlines were traced from a Web Mercator map, so over one county the
 * relation is flat enough to be a plain affine one. These six numbers come
 * from a least-squares fit of the outlines against the Census town
 * boundaries for Monroe County: every inland town centre lands within one
 * unit of its true place, on a map 673 units wide. The lakefront towns are
 * left out of the fit, because the Census polygons run out into Lake Ontario
 * and the outlines stop at the shore.
 */
export function project(
  latitude: number,
  longitude: number
): { x: number; y: number } {
  return {
    x: 1071.323058 * longitude + 1.076929 * latitude + 83514.902645,
    y: 0.5178 * longitude - 1467.296729 * latitude + 63676.747242,
  };
}

/** The smallest box that holds the outline, padded a little for the stroke. */
export function outlineBox(
  m: Municipality,
  pad = 4
): { x: number; y: number; width: number; height: number } {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let x = 0;
  let y = 0;

  const see = (px: number, py: number) => {
    if (px < minX) minX = px;
    if (px > maxX) maxX = px;
    if (py < minY) minY = py;
    if (py > maxY) maxY = py;
  };

  for (const d of m.paths) {
    const tokens = d.match(/[A-Za-z]|-?\d*\.?\d+(?:e[-+]?\d+)?/g) ?? [];
    let command = '';
    let i = 0;

    while (i < tokens.length) {
      const token = tokens[i];
      if (/[A-Za-z]/.test(token)) {
        command = token;
        i += 1;
        continue;
      }
      const next = () => Number(tokens[i++]);

      switch (command) {
        case 'M':
        case 'L':
          x = next();
          y = next();
          see(x, y);
          break;
        case 'H':
          x = next();
          see(x, y);
          break;
        case 'V':
          y = next();
          see(x, y);
          break;
        case 'C':
          // The control points can sit outside the curve, which only makes
          // the box a little larger than it has to be.
          see(next(), next());
          see(next(), next());
          x = next();
          y = next();
          see(x, y);
          break;
        default:
          i += 1;
      }
    }
  }

  const round = (n: number) => Math.round(n * 100) / 100;
  return {
    x: round(minX - pad),
    y: round(minY - pad),
    width: round(maxX - minX + pad * 2),
    height: round(maxY - minY + pad * 2),
  };
}

/** The same box, written the way the `viewBox` attribute wants it. */
export function outlineViewBox(m: Municipality, pad = 4): string {
  const box = outlineBox(m, pad);
  return `${box.x} ${box.y} ${box.width} ${box.height}`;
}
